targets={\"MIPStarRE/QPBT/Combining/Apply.lean\":[\"exists_extendedLinesWitness_ofPointsWitness\",\"exists_extendedLinesWitness\",\"exists_extendedLinesWitness_established_ofPointsWitness\",\"exists_extendedLinesWitness_established\",\"exists_globalPairWitness\"],\"MIPStarRE/QPBT/Combining/Claims.lean\":[\"subline_replace_by_ordered_product\",\"subline_remove_X_factor\",\"subline_Z_term_near_one\"],\"MIPStarRE/QPBT/Combining/Lines.lean\":[\"exists_combinedLinesWitness_ofPointsWitness\",\"exists_combinedLinesWitness\"],\"MIPStarRE/QPBT/Extraction/Consistency.lean\":[\"marginalPoly_sub_pointMeas_approx_zero\",\"nonencodingMarginalMass_le\",\"tildeM_consistent_pointMeas\",\"tildeM_consistent_pointMeas_prime\",\"tildeObs_selfConsistent\"],\"MIPStarRE/QPBT/Extraction/Observables.lean\":[\"swapUnitary_conj_tildeObs\",\"swapUnitary_conj_tildeM\"],\"MIPStarRE/QPBT/Extraction/Unitary.lean\":[\"exists_extractionWitness_ofGlobalPairWitness\"],\"MIPStarRE/QPBT/Games/StrategyClasses.lean\":[\"exists_symmetric_projective_strategy\"],\"MIPStarRE/QPBT/Observables/LineMeasurement.lean\":[\"expLineOp_nonneg\",\"expLineOp_sum_eq_one\",\"lineMeasExp_isProjective\",\"expLineOp_zero_of_not_deg_d\",\"expLine_self_cons\",\"expLine_point_cons\",\"expLine_point_cons_prime\"],\"MIPStarRE/QPBT/Test/Completeness.lean\":[\"exists_spcc_value_one\"],\"MIPStarRE/QPBT/Test/LowDegreeGameTheorems.lean\":[\"exists_ld_soundness\"],\"MIPStarRE/QPBT/Test/QubitForm.lean\":[\"pauli_soundness_qubit\"],\"MIPStarRE/QPBT/Test/Soundness.lean\":[\"pauli_soundness\"]}
# apostrophe names represented as _prime below
aliases={\"tildeM_consistent_pointMeas_prime\":\"tildeM_consistent_pointMeas\\x27\",\"expLine_point_cons_prime\":\"expLine_point_cons\\x27\"}
def show(h,f):
 p=subprocess.run([\"git\",\"show\",f\"{h}:{f}\"],text=True,capture_output=True); return p.stdout if p.returncode==0 else None
def proved(txt,name):
 name=aliases.get(name,name); pat=re.compile(r\"(?m)"'^(?:private |protected |noncomputable )?(?:theorem|lemma|def)'"\\s+\"+re.escape(name)+r\"(?:\\s|\\{|\\(|:)\"); m=pat.search(txt)
 if not m:return False
 nxt=re.search(r\"(?m)"'^(?:private |protected |noncomputable )?(?:theorem|lemma|def|structure|class|abbrev|instance)'"\\s+\",txt[m.end():]); end=m.end()+(nxt.start() if nxt else len(txt)-m.end()); span=txt[m.start():end]
 return not re.search(r\"(?m)"'^[ '"\\t]*sorry(?:[ \\t]|"'$)",span)
closed={}
for p in prs:
 h=p["head"]["sha"]; n=p["number"]
 if subprocess.run(["git","cat-file","-e",h+"''^{commit}"],capture_output=True).returncode: continue
 for f,names in targets.items():
  txt=show(h,f)
  if txt is None: continue
  for name in names:
   if proved(txt,name): closed.setdefault((f,aliases.get(name,name)),[]).append(n)
print("resolved_sites",len(closed))
for (f,n),ps in closed.items(): print(f,n,",".join(map(str,ps)))'"'"

